  {
   "cell_type": "code",
   "execution_count": 0,
   "metadata": {
    "application/vnd.databricks.v1+cell": {
     "cellMetadata": {
      "byteLimit": 2048000,
      "rowLimit": 10000
     },
     "inputWidgets": {},
     "nuid": "85dc76b5-36fe-4225-8dc7-b2c8196aa555",
     "showTitle": false,
     "tableResultSettingsMap": {},
     "title": ""
    }
   },
   "outputs": [],
   "source": [
    "base_df = stockout_df.select(\n",
    "    \"stock_code\",\n",
    "    \"product_name\",\n",
    "    \"category\",\n",
    "    \"brand\",\n",
    "    \"warehouse_id\",\n",
    "    \"available_stock\",\n",
    "    \"avg_daily_sales\",\n",
    "    \"days_of_inventory_remaining\",\n",
    "    \"lead_time_days\",\n",
    "    \"reliability_score\",\n",
    "    \"stockout_risk_level\"\n",
    ")"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 0,
   "metadata": {
    "application/vnd.databricks.v1+cell": {
     "cellMetadata": {
      "byteLimit": 2048000,
      "rowLimit": 10000
     },
     "inputWidgets": {},
     "nuid": "823b87f6-2868-46de-8303-957684f75fbd",
     "showTitle": false,
     "tableResultSettingsMap": {},
     "title": ""
    }
   },
   "outputs": [],
   "source": [
    "expanded_stockout_df = base_df.crossJoin(\n",
    "    spark.range(1, 101).withColumnRenamed(\"id\", \"simulation_id\")\n",
    ").withColumn(\n",
    "    \"available_stock\",\n",
    "    round(col(\"available_stock\") * (lit(0.5) + rand()), 0)\n",
    ").withColumn(\n",
    "    \"avg_daily_sales\",\n",
    "    round(col(\"avg_daily_sales\") * (lit(0.5) + rand()), 2)\n",
    ").withColumn(\n",
    "    \"lead_time_days\",\n",
    "    round(col(\"lead_time_days\") * (lit(0.8) + rand() * lit(0.5)), 0)\n",
    ").withColumn(\n",
    "    \"reliability_score\",\n",
    "    round(col(\"reliability_score\") * (lit(0.9) + rand() * lit(0.2)), 2)\n",
    ")"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 0,
   "metadata": {
    "application/vnd.databricks.v1+cell": {
     "cellMetadata": {
      "byteLimit": 2048000,
      "rowLimit": 10000
     },
     "inputWidgets": {},
     "nuid": "1e3cc74a-db29-46e2-be3e-d346b04f92e2",
     "showTitle": false,
     "tableResultSettingsMap": {},
     "title": ""
    }
   },
   "outputs": [],
   "source": [
    "expanded_stockout_df = expanded_stockout_df.withColumn(\n",
    "    \"days_of_inventory_remaining\",\n",
    "    when(\n",
    "        col(\"avg_daily_sales\") > 0,\n",
    "        round(col(\"available_stock\") / col(\"avg_daily_sales\"), 2)\n",
    "    ).otherwise(None)\n",
    ")"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 0,
   "metadata": {
    "application/vnd.databricks.v1+cell": {
     "cellMetadata": {
      "byteLimit": 2048000,
      "rowLimit": 10000
     },
     "inputWidgets": {},
     "nuid": "14411fa0-4734-4bf3-b2d1-255aca6540f4",
     "showTitle": false,
     "tableResultSettingsMap": {},
     "title": ""
    }
   },
   "outputs": [],
   "source": [
    "expanded_stockout_df = expanded_stockout_df.withColumn(\n",
    "    \"stockout_risk_level\",\n",
    "    when(col(\"avg_daily_sales\") == 0, \"No Recent Sales\")\n",
    "    .when(col(\"days_of_inventory_remaining\") <= col(\"lead_time_days\"), \"High Risk\")\n",
    "    .when(col(\"days_of_inventory_remaining\") <= col(\"lead_time_days\") + 7, \"Medium Risk\")\n",
    "    .otherwise(\"Low Risk\")\n",
    ")"
   ]
  },
