    "\n",
    "reorder_preprocessor = ColumnTransformer(\n",
    "    transformers=[\n",
    "        (\"categorical\", OneHotEncoder(handle_unknown=\"ignore\"), categorical_features_reorder),\n",
    "        (\"numeric\", \"passthrough\", numeric_features_reorder)\n",
    "    ]\n",
    ")"
